class SettingsOptimizer:
    def __init__(self, *, max_local_trials: int = 6, total_budget: int = 64) -> None:
        self.max_local_trials = max(0, int(max_local_trials)); self.total_budget = max(0, int(total_budget)); self.consumed = 0

